const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const PORT = process.env.PORT || 3002;
const rooms = new Map();
const mime = { '.html':'text/html; charset=utf-8', '.js':'text/javascript; charset=utf-8', '.css':'text/css; charset=utf-8', '.json':'application/json' };
const server = http.createServer((req, res) => {
  const pathname = new URL(req.url, 'http://localhost').pathname;
  if (pathname === '/api/room') {
    res.writeHead(200, {'Content-Type':'application/json'});
    res.end(JSON.stringify({ room: process.env.ROOM_CODE || 'ASHFALL', players: rooms.get(process.env.ROOM_CODE || 'ASHFALL')?.size || 0 })); return;
  }
  let file = path.join(__dirname, pathname === '/' ? 'index.html' : pathname);
  if (!file.startsWith(__dirname)) { res.writeHead(403); res.end(); return; }
  fs.readFile(file, (err, data) => { if (err) { res.writeHead(404); res.end('Not found'); return; } res.writeHead(200, {'Content-Type': mime[path.extname(file)] || 'application/octet-stream'}); res.end(data); });
});
server.on('upgrade', (req, socket) => {
  if (req.url !== '/play') { socket.destroy(); return; }
  const key = req.headers['sec-websocket-key']; if (!key) { socket.destroy(); return; }
  const accept = crypto.createHash('sha1').update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
  socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + accept + '\r\n\r\n');
  const roomCode = process.env.ROOM_CODE || 'ASHFALL';
  if (!rooms.has(roomCode)) rooms.set(roomCode, new Set());
  const room = rooms.get(roomCode), player = { socket, id: crypto.randomBytes(4).toString('hex'), x: 0, z: 0, yaw: 0, name: 'Wanderer', alive: true };
  room.add(player);
  function send(obj) { if (socket.destroyed) return; const body = Buffer.from(JSON.stringify(obj)); let head; if (body.length < 126) head = Buffer.from([0x81, body.length]); else { head = Buffer.alloc(4); head[0]=0x81; head[1]=126; head.writeUInt16BE(body.length,2); } socket.write(Buffer.concat([head, body])); }
  function broadcast() { const state = Array.from(room).map(p => ({id:p.id,name:p.name,x:p.x,z:p.z,yaw:p.yaw,alive:p.alive})); for (const p of room) { if (p.socket !== socket) { const body=Buffer.from(JSON.stringify({type:'players',players:state})); const head=body.length<126?Buffer.from([129,body.length]):Buffer.from([129,126,(body.length>>8)&255,body.length&255]); if (!p.socket.destroyed) p.socket.write(Buffer.concat([head,body])); } } }
  send({type:'welcome',id:player.id,room:roomCode,players:Array.from(room).filter(p=>p!==player).map(p=>({id:p.id,name:p.name,x:p.x,z:p.z,yaw:p.yaw,alive:p.alive}))}); broadcast();
  let buffer=Buffer.alloc(0);
  socket.on('data', chunk => { buffer=Buffer.concat([buffer,chunk]); while(buffer.length>=2){ let len=buffer[1]&127, offset=2; if(len===126){if(buffer.length<4)break;len=buffer.readUInt16BE(2);offset=4;}else if(len===127){socket.destroy();return;} const masked=!!(buffer[1]&128); if(masked)offset+=4; if(buffer.length<offset+len)break; let payload=buffer.subarray(offset,offset+len); if(masked){const mask=buffer.subarray(offset-4,offset);payload=Buffer.from(payload);for(let i=0;i<len;i++)payload[i]^=mask[i%4];} buffer=buffer.subarray(offset+len); try{const msg=JSON.parse(payload.toString()); if(msg.type==='move'){player.x=Math.max(-36,Math.min(36,Number(msg.x)||0));player.z=Math.max(-36,Math.min(36,Number(msg.z)||0));player.yaw=Number(msg.yaw)||0;player.alive=!!msg.alive;player.name=String(msg.name||'Wanderer').slice(0,16);broadcast();} else if(msg.type==='chat'){const chat={type:'chat',name:player.name,text:String(msg.text||'').slice(0,120)};for(const p of room){if(!p.socket.destroyed){const body=Buffer.from(JSON.stringify(chat));const head=body.length<126?Buffer.from([129,body.length]):Buffer.from([129,126,body.length>>8,body.length&255]);p.socket.write(Buffer.concat([head,body]));}}}}catch(e){} } });
  socket.on('close',()=>{room.delete(player);broadcast();}); socket.on('error',()=>{room.delete(player);});
});
server.listen(PORT, '0.0.0.0', () => console.log(`Ashfall listening on ${PORT}`));

(()=>{
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');let W,H,dpr=1;function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const $=s=>document.querySelector(s),ui={start:$('#startScreen'),play:$('#playBtn'),name:$('#playerName'),room:$('#roomInput'),help:$('#helpModal'),hp:$('#healthBar'),hpText:$('#healthText'),st:$('#staminaBar'),stText:$('#staminaText'),shards:$('#shards'),shardCount:$('#shardCount'),embers:$('#emberCount'),kits:$('#kitCount'),progress:$('#progress'),shrine:$('#shrineCount'),players:$('#players'),roomLabel:$('#roomLabel'),prompt:$('#prompt'),target:$('#target'),toast:$('#toast'),feed:$('#feed'),damage:$('#damageFlash'),death:$('#death')};
let running=false,keys={},mouse={x:innerWidth/2,y:innerHeight/2,down:false},player={x:0,z:0,yaw:0,hp:100,st:100,alive:true,name:'Wanderer',id:'local',embers:0,shards:0,kits:0,attack:0,dodge:0,hitTimer:0},others=new Map(),ws=null,worldSeed=0x5a17,camYaw=0,camDist=11,day=1,night=0,killCount=0,shrineCount=0,locked=false,toastTimer=0,walk=0;
function random(){worldSeed=(worldSeed*1664525+1013904223)>>>0;return worldSeed/4294967296}const nodes=[],shrines=[],mobs=[],props=[];for(let i=0;i<78;i++){let x=(random()-.5)*72,z=(random()-.5)*72;if(Math.hypot(x,z)<6){i--;continue}props.push({x,z,r:.4+random()*.8,type:random()<.58?'rock':'tree',h:1+random()*2})}for(let i=0;i<17;i++){let x=(random()-.5)*62,z=(random()-.5)*62;if(Math.hypot(x,z)<8){i--;continue}nodes.push({x,z,hp:3,alive:true,glow:random()});}for(let i=0;i<3;i++){let a=i*2.094+random()*.5,r=15+random()*9;shrines.push({x:Math.cos(a)*r,z:Math.sin(a)*r,awake:false,index:i});}for(let i=0;i<7;i++){let a=random()*Math.PI*2,r=14+random()*25;mobs.push({x:Math.cos(a)*r,z:Math.sin(a)*r,hp:2+(i%3),max:2+(i%3),type:i<4?'imp':'wraith',phase:random()*8,attack:0,dead:false});}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);function msg(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}function feed(text){const d=document.createElement('div');d.textContent='✧ '+text;ui.feed.prepend(d);while(ui.feed.children.length>3)ui.feed.lastChild.remove();setTimeout(()=>d.remove(),5000)}function refresh(){ui.hp.style.width=player.hp+'%';ui.hpText.textContent=Math.ceil(player.hp);ui.st.style.width=player.st+'%';ui.stText.textContent=Math.floor(player.st);ui.shards.textContent=player.shards;ui.shardCount.textContent=player.shards;ui.embers.textContent=player.embers;ui.kits.textContent=player.kits;ui.progress.style.width=(shrineCount/3*100)+'%';ui.shrine.textContent=`${shrineCount} / 3 SHRINES AWAKENED`;ui.players.textContent=others.size+1}
function start(){if(running)return;running=true;player.name=(ui.name.value.trim()||'Wanderer').slice(0,16);const room=(ui.room.value.trim()||'ASHFALL').toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,16)||'ASHFALL';ui.roomLabel.textContent=room;ui.start.classList.add('hidden');connect(room);msg('The ash remembers your name.');feed('Gather emberstone. Find the shrines.');requestAnimationFrame(loop)}
function connect(room){try{const proto=location.protocol==='https:'?'wss:':'ws:';ws=new WebSocket(`${proto}//${location.host}/play`);ws.onopen=()=>{feed('Connected to the shared veil.');sendMove()};ws.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch{return}if(m.type==='welcome'){player.id=m.id;ui.roomLabel.textContent=m.room;for(const p of m.players||[])others.set(p.id,p);refresh()}if(m.type==='players'){others.clear();for(const p of m.players||[])if(p.id!==player.id)others.set(p.id,p);refresh()}if(m.type==='chat')feed(`${m.name}: ${m.text}`)};ws.onclose=()=>{if(running)feed('Veil connection lost — continuing alone.')}}catch(e){}}
function sendMove(){if(ws&&ws.readyState===1)ws.send(JSON.stringify({type:'move',x:player.x,z:player.z,yaw:player.yaw,alive:player.alive,name:player.name}))}let sendClock=0;
function project(x,z,y=0){const dx=x-player.x,dz=z-player.z,c=Math.cos(camYaw),s=Math.sin(camYaw),rx=dx*c-dz*s,rz=dx*s+dz*c;const focal=Math.min(W,H)*.92,depth=rz+10;if(depth<.18)return null;const scale=focal/depth;return {x:W/2+rx*scale,y:H*.52+(1.45-y)*scale,scale,depth}}
function ground(){let horizon=H*.37;let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#2a1c24');sky.addColorStop(.55,'#73504a');sky.addColorStop(.57,'#60423b');sky.addColorStop(1,'#271e20');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const sun=ctx.createRadialGradient(W*.74,horizon-12,3,W*.74,horizon-12,95);sun.addColorStop(0,'#efbd79aa');sun.addColorStop(.25,'#d9856080');sun.addColorStop(1,'#c4674a00');ctx.fillStyle=sun;ctx.fillRect(W*.55,horizon-120,W*.4,220);ctx.fillStyle='#39292c';ctx.beginPath();ctx.moveTo(0,horizon+8);for(let x=0;x<=W;x+=40)ctx.lineTo(x,horizon+random()*27);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();let v=ctx.createRadialGradient(W*.5,H*.48,20,W*.5,H*.5,Math.max(W,H)*.8);v.addColorStop(0,'#96705b');v.addColorStop(.5,'#675047');v.addColorStop(1,'#342b2d');ctx.fillStyle=v;ctx.fillRect(0,horizon,H?W:W,H-horizon);for(let i=0;i<150;i++){let x=(i*173.7+Math.sin(i*17)*50)%W,y=horizon+((i*97.3)%Math.max(1,H-horizon)),r=(i%3)*.45+.4;ctx.fillStyle=i%4?'#d8a58015':'#f0ca991f';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill()}}
function drawRock(p){let q=project(p.x,p.z,.12);if(!q||q.scale<1.6)return;let r=clamp(p.r*q.scale*.38,1,25);ctx.fillStyle='#44383a';ctx.beginPath();ctx.ellipse(q.x,q.y,r*1.35,r*.55,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70605a';ctx.beginPath();ctx.moveTo(q.x-r,q.y);ctx.lineTo(q.x-r*.55,q.y-r*.65);ctx.lineTo(q.x+r*.15,q.y-r*.8);ctx.lineTo(q.x+r,q.y-r*.2);ctx.lineTo(q.x+r*.7,q.y+r*.2);ctx.closePath();ctx.fill();ctx.strokeStyle='#c5885728';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x-r*.2,q.y-r*.62);ctx.lineTo(q.x-r*.05,q.y-r*.1);ctx.stroke()}
function drawTree(p){let q=project(p.x,p.z,0);if(!q||q.scale<1.5)return;let s=clamp(q.scale*.16,1,24);ctx.fillStyle='#261d21';ctx.fillRect(q.x-s*.12,q.y-s*1.15,s*.24,s*1.1);ctx.fillStyle='#312127';ctx.beginPath();ctx.moveTo(q.x,q.y-s*2.4);ctx.lineTo(q.x-s*.75,q.y-s*.55);ctx.lineTo(q.x+s*.7,q.y-s*.55);ctx.closePath();ctx.fill();ctx.fillStyle='#49302d';ctx.beginPath();ctx.moveTo(q.x,q.y-s*1.85);ctx.lineTo(q.x-s*.55,q.y-s*.25);ctx.lineTo(q.x+s*.6,q.y-s*.25);ctx.closePath();ctx.fill()}
function drawNode(n){if(!n.alive)return;let q=project(n.x,n.z,.15);if(!q||q.scale<1)return;let r=clamp(q.scale*.35,2,20),pulse=.75+Math.sin(performance.now()/400+n.glow*6)*.25;ctx.shadowBlur=14*pulse;ctx.shadowColor='#df8750';ctx.fillStyle='#c47c4f';ctx.beginPath();ctx.moveTo(q.x-r,q.y);ctx.lineTo(q.x-r*.55,q.y-r*1.3);ctx.lineTo(q.x+r*.15,q.y-r*1.55);ctx.lineTo(q.x+r,q.y-r*.6);ctx.lineTo(q.x+r*.8,q.y+r*.15);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffd28b';ctx.globalAlpha=pulse;ctx.beginPath();ctx.moveTo(q.x-r*.2,q.y-r*.95);ctx.lineTo(q.x+r*.18,q.y-r*.3);ctx.stroke();ctx.globalAlpha=1}
function drawShrine(sh){let q=project(sh.x,sh.z,.1);if(!q||q.scale<1)return;let r=clamp(q.scale*.42,3,28),pulse=.6+.4*Math.sin(performance.now()/600+sh.index);ctx.shadowBlur=sh.awake?28:17;ctx.shadowColor=sh.awake?'#f1bd76':'#ab69cf';ctx.strokeStyle=sh.awake?'#f4c27b':'#c596df';ctx.lineWidth=Math.max(1,q.scale*.012);ctx.beginPath();ctx.arc(q.x,q.y-r*.65,r*.75,0,Math.PI*2);ctx.stroke();ctx.fillStyle=sh.awake?'#f2bd6d':'#8c5caa';ctx.beginPath();ctx.moveTo(q.x,q.y-r*1.65);ctx.lineTo(q.x-r*.7,q.y-r*.2);ctx.lineTo(q.x+r*.7,q.y-r*.2);ctx.closePath();ctx.fill();ctx.fillStyle='#292025';ctx.fillRect(q.x-r*.7,q.y-r*.2,r*1.4,r*.35);ctx.shadowBlur=0;if(!sh.awake){ctx.fillStyle=`rgba(222,181,255,${.35+pulse*.45})`;ctx.beginPath();ctx.arc(q.x,q.y-r*.55,Math.max(2,r*.18),0,7);ctx.fill()}}
function drawMob(m){if(m.dead)return;let bob=Math.sin(performance.now()/260+m.phase)*.12,q=project(m.x,m.z,m.type==='wraith'?1.25+bob:.12);if(!q||q.scale<1)return;let s=clamp(q.scale*.27,2,24);if(m.type==='imp'){ctx.fillStyle='#251217';ctx.beginPath();ctx.ellipse(q.x,q.y-s*.45,s*.48,s*.52,0,0,7);ctx.fill();ctx.fillStyle='#732d2d';ctx.beginPath();ctx.moveTo(q.x-s*.4,q.y-s*.72);ctx.lineTo(q.x-s*.75,q.y-s*1.25);ctx.lineTo(q.x-s*.16,q.y-s*.94);ctx.fill();ctx.beginPath();ctx.moveTo(q.x+s*.35,q.y-s*.7);ctx.lineTo(q.x+s*.65,q.y-s*1.2);ctx.lineTo(q.x+s*.14,q.y-s*.91);ctx.fill();ctx.fillStyle='#ffab62';ctx.fillRect(q.x-s*.25,q.y-s*.65,s*.11,s*.07);ctx.fillRect(q.x+s*.15,q.y-s*.65,s*.11,s*.07)}else{ctx.fillStyle='#171923b8';ctx.beginPath();ctx.ellipse(q.x,q.y-s*.5,s*.45,s*.85,0,0,7);ctx.fill();ctx.strokeStyle='#8c73bd';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x-s*.1,q.y-s*.9);ctx.lineTo(q.x-s*.42,q.y-s*1.4);ctx.moveTo(q.x+s*.08,q.y-s*.9);ctx.lineTo(q.x+s*.42,q.y-s*1.3);ctx.stroke();ctx.fillStyle='#bb9aff';ctx.fillRect(q.x-s*.18,q.y-s*.58,s*.1,s*.06);ctx.fillRect(q.x+s*.09,q.y-s*.58,s*.1,s*.06)}ctx.fillStyle='#0009';ctx.fillRect(q.x-s*.45,q.y-s*1.6,s*.9,2);ctx.fillStyle='#c65754';ctx.fillRect(q.x-s*.45,q.y-s*1.6,s*.9*(m.hp/m.max),2)}
function drawOther(p){let q=project(p.x,p.z,.12);if(!q||q.scale<1)return;let s=clamp(q.scale*.23,2,19);ctx.fillStyle='#252535';ctx.beginPath();ctx.ellipse(q.x,q.y-s*.48,s*.35,s*.48,0,0,7);ctx.fill();ctx.fillStyle='#c4a878';ctx.beginPath();ctx.arc(q.x,q.y-s*1.08,s*.22,0,7);ctx.fill();ctx.fillStyle='#efc47e';ctx.fillText(p.name,q.x-ctx.measureText(p.name).width/2,q.y-s*1.55)}
function drawPlayer(){ctx.save();ctx.translate(W/2,H*.58);let s=clamp(Math.min(W,H)*.0015, .65,1.15),bob=Math.sin(walk)*2;ctx.scale(s,s);ctx.fillStyle='#0c0b10';ctx.beginPath();ctx.ellipse(0,35,32,8,0,0,7);ctx.fill();ctx.fillStyle='#29232c';ctx.beginPath();ctx.moveTo(-20,25);ctx.lineTo(-14,-18);ctx.lineTo(-10,-40);ctx.lineTo(10,-40);ctx.lineTo(16,-17);ctx.lineTo(21,25);ctx.closePath();ctx.fill();ctx.fillStyle='#48404a';ctx.beginPath();ctx.moveTo(-12,-35);ctx.lineTo(0,-44);ctx.lineTo(12,-35);ctx.lineTo(8,-5);ctx.lineTo(-8,-5);ctx.closePath();ctx.fill();ctx.fillStyle='#bb8e69';ctx.beginPath();ctx.arc(0,-52+bob,10,0,7);ctx.fill();ctx.fillStyle='#18141a';ctx.beginPath();ctx.arc(0,-55+bob,11,Math.PI,Math.PI*2);ctx.fill();ctx.strokeStyle='#d5a35c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(14,-22);ctx.lineTo(28,-49);ctx.stroke();ctx.strokeStyle='#fff0c1';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(28,-49);ctx.lineTo(35,-62);ctx.stroke();if(player.attack>0){ctx.strokeStyle='#ffe2a2';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-10,68,-1.2,1.0);ctx.stroke();}if(player.dodge>0){ctx.globalAlpha=.4;ctx.fillStyle='#d09d64';ctx.beginPath();ctx.ellipse(-player.dodge*50,0,20,45,0,0,7);ctx.fill()}ctx.restore()}
function render(){ground();let list=[];for(const p of props)list.push({d:Math.hypot(p.x-player.x,p.z-player.z),draw:()=>p.type==='rock'?drawRock(p):drawTree(p)});for(const n of nodes)if(n.alive)list.push({d:Math.hypot(n.x-player.x,n.z-player.z),draw:()=>drawNode(n)});for(const s of shrines)list.push({d:Math.hypot(s.x-player.x,s.z-player.z),draw:()=>drawShrine(s)});for(const m of mobs)if(!m.dead)list.push({d:Math.hypot(m.x-player.x,m.z-player.z),draw:()=>drawMob(m)});for(const p of others.values())list.push({d:Math.hypot(p.x-player.x,p.z-player.z),draw:()=>drawOther(p)});list.sort((a,b)=>b.d-a.d).forEach(o=>o.draw());drawPlayer();const near=findNearby();ui.prompt.textContent=near?near.type==='node'?'[ E ]  GATHER EMBERSTONE':near.type==='shrine'?'[ E ]  AWAKEN SHRINE':'[ E ]  GATHER SPOILS':'';ui.target.textContent='';}
function findNearby(){let best=null,bd=2.3;for(const n of nodes)if(n.alive&&dist(player,n)<bd){best={type:'node',obj:n};bd=dist(player,n)}for(const s of shrines)if(!s.awake&&dist(player,s)<bd){best={type:'shrine',obj:s};bd=dist(player,s)}return best}
